To build an Express.js REST API that stores and retrieves customer data from a MongoDB database, follow these steps:

1. Set up a new Node.js project and install Express.js, MongoDB, and any other dependencies required for your project.

2. Create a new MongoDB database or use an existing one to store the customer data. Create a collection for customer data and define the schema for the customer object.

3. Create a new Express.js app and define the basic routes for the customer resource, including GET, POST, PUT, and DELETE methods.

4. Use the MongoDB Node.js driver to connect to the MongoDB database and perform CRUD operations on the customer data. Handle errors that may occur during database operations and return appropriate error messages or HTTP status codes.

5. Implement error handling middleware to catch any unhandled errors that occur during request processing and return appropriate error messages or HTTP status codes.

6. Use middleware to handle JSON body parsing and validation of the customer data before inserting it into the database or updating an existing customer.

7. Follow RESTful design principles when designing the API, including using meaningful resource names, HTTP methods, and status codes to indicate the intent of each request.

Here's an example code structure for a basic Express.js REST API that handles customer data:

```
const express = require('express');
const MongoClient = require('mongodb').MongoClient;
const bodyParser = require('body-parser');
const app = express();

const port = 3000;
const dbName = 'customer-db';
const collectionName = 'customers';

// Middleware to handle JSON body parsing
app.use(bodyParser.json());

// Connect to MongoDB database
MongoClient.connect('mongodb://localhost:27017/', (err, client) => {
  if (err) {
    console.log(err);
    process.exit(1);
  }
  const db = client.db(dbName);
  const collection = db.collection(collectionName);

  // Routes for customer resource
  app.get('/customers', async (req, res) => {
    try {
      const data = await collection.find({}).toArray();
      res.status(200).json(data);
    } catch (error) {
      res.status(500).json({ message: 'Internal server error' });
    }
  });

  app.get('/customers/:id', async (req, res) => {
    try {
      const data = await collection.findOne({ _id: req.params.id });
      if (data) {
        res.status(200).json(data);
      } else {
        res.status(404).json({ message: 'Customer not found' });
      }
    } catch (error) {
      res.status(500).json({ message: 'Internal server error' });
    }
  });

  app.post('/customers', async (req, res) => {
    try {
      const result = await collection.insertOne(req.body);
      res.status(201).json(result.ops[0]);
    } catch (error) {
      res.status(400).json({ message: 'Invalid request body' });
    }
  });

  app.put('/customers/:id', async (req, res) => {
    try {
      const result = await collection.findOneAndUpdate(
        { _id: req.params.id },
        { $set: req.body },
        { returnOriginal: false }
      );
      if (result.value) {
        res.status(200).json(result.value);
      } else {
        res.status(404).json({ message: 'Customer not found' });
      }
    } catch (error) {
      res.status(400).json({ message: 'Invalid request body' });
    }
  });

  app.delete('/customers/:id', async (req, res) => {
    try {
      const result = await collection.findOneAndDelete({ _id: req.params.id });
      if (result.value) {
        res.status(200).json(result.value);
      } else {
        res.status(404).json({ message: 'Customer not found' });
      }
    } catch (error) {
      res.status(500).json({ message: 'Internal server error' });
    }
  });

  // Error handling middleware
  app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).json({ message: 'Internal server error' });
  });

  app.listen(port, () => {
    console.log(`Server listening on port ${port}`);
  });
});
```
